const entrada = $json.body ?? $json;
const ativo = String(entrada.ativo ?? 'exemplo de investimento').trim();
const pergunta = String(entrada.pergunta ?? 'Explique este assunto para um iniciante.').trim();

if (!ativo || !pergunta) {
  return [{ json: { ok: false, erro: 'Informe os campos ativo e pergunta.' } }];
}

return [{
  json: {
    ok: true,
    projeto: 'InvestIA',
    modo: 'demonstracao_educacional',
    ativo,
    pergunta,
    dados: {
      origem: 'dados ficticios de demonstracao',
      valor_exemplo_brl: 100,
      variacao_percentual_exemplo: 2.5
    },
    mensagem: `Recebi sua solicitação sobre ${ativo}. Este MVP ainda usa números fictícios para demonstrar o fluxo. A variação de exemplo é 2,5% sobre um valor ilustrativo de R$ 100. Isso não representa cotação real nem recomendação de investimento. Pergunta recebida: ${pergunta}`,
    aviso: 'Projeto educacional. Os dados são fictícios; não use esta resposta para tomar decisões financeiras.'
  }
}];
